mapper.select:
SELECT u.user_id, u.user_name, u.user_nickname, u.user_role, u.user_amount, u.user_personal_signature, u.create_time FROM ch_user u WHERE u.user_is_delete = 0
AND (u.create_time < #{cursorTime} OR (u.create_time = #{cursorTime} AND u.user_id < #{cursorId}))
ORDER BY u.create_time DESC, u.user_id DESC LIMIT #{pageSize}

SELECT p.post_id, p.post_title, p.post_type, p.post_user_id, u.user_nickname AS post_user_nickname, p.post_view_number, p.post_like_number, p.post_collect_number, p.create_time FROM ch_post p LEFT JOIN ch_user u ON u.user_id = p.post_user_id AND u.user_is_delete = 0 WHERE p.post_is_delete = 0
AND (p.create_time < #{cursorTime} OR (p.create_time = #{cursorTime} AND p.post_id < #{cursorId}))
ORDER BY p.create_time DESC, p.post_id DESC LIMIT #{pageSize}

SELECT s.shop_id, s.shop_name, s.shop_user_id, u.user_nickname AS shop_user_nickname, s.shop_description, s.create_time FROM ch_shop s LEFT JOIN ch_user u ON u.user_id = s.shop_user_id AND u.user_is_delete = 0 WHERE s.shop_is_delete = 0
AND (s.create_time < #{cursorTime} OR (s.create_time = #{cursorTime} AND s.shop_id < #{cursorId}))
ORDER BY s.create_time DESC, s.shop_id DESC LIMIT #{pageSize}

SELECT p.product_id, p.product_name, p.product_shop_id, s.shop_name, p.product_price, p.product_stock, p.product_stock_locked, p.product_status, p.create_time FROM ch_product p LEFT JOIN ch_shop s ON s.shop_id = p.product_shop_id AND s.shop_is_delete = 0 WHERE p.product_is_delete = 0
AND (p.create_time < #{cursorTime} OR (p.create_time = #{cursorTime} AND p.product_id < #{cursorId}))
ORDER BY p.create_time DESC, p.product_id DESC LIMIT #{pageSize}
